import heapq

RESOURCES = {
    'vnet': [],
    'subnet': ['vnet'],
    'nsg': [],
    'nic': ['subnet', 'nsg'],
    'vm': ['nic', 'storage'],
    'storage': [],
}

def deployment_order(resources):
    deps = {name: set(d) for name, d in resources.items()}
    for d in list(deps.values()):
        for x in d:
            deps.setdefault(x, set())
    dependents = {name: [] for name in deps}
    indegree = {}
    for name, d in deps.items():
        indegree[name] = len(d)
        for x in d:
            dependents[x].append(name)

    ready = [n for n, k in indegree.items() if k == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for nxt in dependents[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(ready, nxt)
    if len(order) != len(deps):
        raise ValueError("cycle detected in resource dependencies")
    return order

order = deployment_order(RESOURCES)
for i, name in enumerate(order, 1):
    print(f"{i}. {name}")

order = deployment_order(RESOURCES)
assert order == ['nsg', 'storage', 'vnet', 'subnet', 'nic', 'vm']
assert deployment_order({'a': [], 'b': ['a']}) == ['a', 'b']
assert deployment_order({'z': [], 'a': ['z']}) == ['z', 'a']
pos = {n: i for i, n in enumerate(order)}
for name, deps in RESOURCES.items():
    for d in deps:
        assert pos[d] < pos[name]
